    {
      "name": "Finsupp.card_support_le_one",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] [Nonempty α] {f : α →₀ M} : f.support.card ≤ 1 ↔ ∃ a, f = fun₀ | a => f a",
      "module": "Mathlib.Data.Finsupp.Single"
    },
    {
      "name": "Submodule.mem_span_set_iff_exists_finsupp_le_finrank",
      "type": " {K : Type u_2} {M : Type u_3} [DivisionRing K] [AddCommGroup M] [Module K M] {s : Set M} {x : M} [Module.Finite K ↥(Submodule.span K s)] : x ∈ Submodule.span K s ↔ ∃ c, c.support.card ≤ Module.finrank K ↥(Submodule.span K s) ∧ ↑c.support ⊆ s ∧ (c.sum fun mi r => r • mi) = x",
      "module": "Mathlib.LinearAlgebra.Dimension.StrongRankCondition"
    },
    {
      "name": "Polynomial.coeff_prod_of_natDegree_le",
      "type": " {R : Type u} {ι : Type w} (s : Finset ι) [CommSemiring R] (f : ι → Polynomial R) (n : ℕ) (h : ∀ p ∈ s, (f p).natDegree ≤ n) : (∏ i ∈ s, f i).coeff (s.card * n) = ∏ i ∈ s, (f i).coeff n",
      "module": "Mathlib.Algebra.Polynomial.BigOperators"
    },
    {
      "name": "Nat.factorization_choose'",
      "type": " {p n k b : ℕ} (hp : Nat.Prime p) (hnb : Nat.log p (n + k) < b) : ((n + k).choose k).factorization p = {i ∈ Finset.Ico 1 b | p ^ i ≤ k % p ^ i + n % p ^ i}.card",
      "module": "Mathlib.Data.Nat.Choose.Factorization"
    },
    {
      "name": "Nat.factorization_choose",
      "type": " {p n k b : ℕ} (hp : Nat.Prime p) (hkn : k ≤ n) (hnb : Nat.log p n < b) : (n.choose k).factorization p = {i ∈ Finset.Ico 1 b | p ^ i ≤ k % p ^ i + (n - k) % p ^ i}.card",
      "module": "Mathlib.Data.Nat.Choose.Factorization"
    },
    {
      "name": "setBasisOfTopLeSpanOfCardEqFinrank_repr_apply",
      "type": " {R : Type u_1} {M : Type u_2} [Semiring R] [OrzechProperty R] [AddCommMonoid M] [Module R M] {s : Set M} [Fintype ↑s] (le_span : ⊤ ≤ Submodule.span R s) (card_eq : s.toFinset.card = Module.finrank R M) (x : M) : (setBasisOfTopLeSpanOfCardEqFinrank le_span card_eq).repr x = ⋯.repr ((LinearMap.codRestrict (Submodule.span R (Set.range Subtype.val)) LinearMap.id ⋯) x)",
      "module": "Mathlib.LinearAlgebra.Dimension.OrzechProperty"
    },
    {
      "name": "finsetBasisOfTopLeSpanOfCardEqFinrank_repr_apply",
      "type": " {R : Type u_1} {M : Type u_2} [Semiring R] [OrzechProperty R] [AddCommMonoid M] [Module R M] {s : Finset M} (le_span : ⊤ ≤ Submodule.span R ↑s) (card_eq : s.card = Module.finrank R M) (x : M) : (finsetBasisOfTopLeSpanOfCardEqFinrank le_span card_eq).repr x = ⋯.repr ((LinearMap.codRestrict (Submodule.span R (Set.range Subtype.val)) LinearMap.id ⋯) x)",
      "module": "Mathlib.LinearAlgebra.Dimension.OrzechProperty"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_totalDegree",
      "type": " {R : Type u_1} [CommRing R] [IsDomain R] [DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R} (hp : p ≠ 0) (S : Finset R) : ↑{f ∈ Fintype.piFinset fun x => S | (MvPolynomial.eval f) p = 0}.card / ↑S.card ^ n ≤ ↑p.totalDegree / ↑S.card",
      "module": "Mathlib.Algebra.MvPolynomial.SchwartzZippel"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sum_degreeOf",
      "type": " {R : Type u_1} [CommRing R] [IsDomain R] [DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R} (hp : p ≠ 0) (S : Fin n → Finset R) : ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤ ∑ i, ↑(MvPolynomial.degreeOf i p) / ↑(S i).card",
      "module": "Mathlib.Algebra.MvPolynomial.SchwartzZippel"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "type": " {R : Type u_1} [CommRing R] [IsDomain R] [DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R} (hp : p ≠ 0) (S : Fin n → Finset R) : ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤ p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card",
      "module": "Mathlib.Algebra.MvPolynomial.SchwartzZippel"
    },
    {
      "name": "Finset.prod_X_add_C_coeff",
      "type": " {R : Type u_1} [CommSemiring R] {σ : Type u_2} (s : Finset σ) (r : σ → R) {k : ℕ} (h : k ≤ s.card) : (∏ i ∈ s, (Polynomial.X + Polynomial.C (r i))).coeff k = ∑ t ∈ Finset.powersetCard (s.card - k) s, ∏ i ∈ t, r i",
      "module": "Mathlib.RingTheory.Polynomial.Vieta"
    }
  ]
